def svg(d):
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 950 {d["height"]}" role="img" aria-label="{esc(d["name"])}"><defs><marker id="arrow-{D.index(d)+1}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#708096"/></marker></defs><style>text{{font-family:system-ui,sans-serif}}.edge{{fill:none;stroke:#708096;stroke-width:1.6}}.label{{font-size:13px;fill:#45566b;paint-order:stroke;stroke:#f8fafc;stroke-width:5px;stroke-linejoin:round}}.node{{cursor:pointer}}.node:hover rect,.node:hover polygon{{stroke-width:3}}</style><rect width="950" height="{d["height"]}" fill="#f8fafc"/>']
 lookup={n[0]:n for n in d['nodes']}
 for idx,(a,b,label) in enumerate(d['edges']):
  aa=lookup[a];bb=lookup[b];_,x,y,w,h,*_=aa;_,xx,yy,ww,hh,*_=bb
  ax=x+w/2;ay=y+h;bx=xx+ww/2;by=yy
  if a=='resume' and b=='render' and 'Corrections' in d['name']:
   ax=x+w;ay=y+h/2;bx=xx+ww;by=yy+hh/2
   path=f'M{ax},{ay}H938V{by}H{bx}';lx=780;ly=ay-10
  elif abs(yy-y)<10:
   ax=x+w/2;bx=xx+ww/2
   if xx>x: ay=y;by=yy;rail=y-24
   else: ay=y+h;by=yy+hh;rail=y+h+25
   path=f'M{ax},{ay}V{rail}H{bx}V{by}';lx=(ax+bx)/2;ly=rail-7 if xx>x else rail+17
  elif yy<y:
   ax=x if xx<x else x+w;ay=y+h/2;bx=xx if xx<x else xx+ww;by=yy+hh/2
   rail=min(x,xx)-9 if xx<x else max(x+w,xx+ww)+9
   path=f'M{ax},{ay}H{rail}V{by}H{bx}';lx=rail+5;ly=(ay+by)/2
  elif abs(ax-bx)<3:
   path=f'M{ax},{ay}V{by}';lx=ax+8;ly=(ay+by)/2
  else:
   mid=by-28 if by-ay>160 else ay+(by-ay)*.5
   path=f'M{ax},{ay}V{mid}H{bx}V{by}';lx=(ax+bx)/2;ly=mid-7
  out.append(f'<path class="edge" d="{path}" marker-end="url(#arrow-{D.index(d)+1})"/>')
  if label:out.append(f'<text class="label" x="{lx}" y="{ly}" text-anchor="middle">{esc(label)}</text>')
 for key,x,y,w,h,label,g,decision in d['nodes']:
  status=gates[g]['current'] if g else 'decision';fill={'manual':'#eaf2ff','mixed':'#fff3d8','automated':'#e3f4ec','decision':'#fff'}[status];stroke={'manual':'#7199d0','mixed':'#ca9234','automated':'#39885c','decision':'#91a1b4'}[status]
  out.append(f'<g class="node" data-gate="{g}" tabindex="0" role="button" aria-label="{esc(label)}"><title>{esc(label)}'+(f' — {status} coverage; click for gate details' if g else '')+'</title>')
  if decision:out.append(f'<polygon points="{x+20},{y} {x+w-20},{y} {x+w},{y+h/2} {x+w-20},{y+h} {x+20},{y+h} {x},{y+h/2}" fill="{fill}" stroke="{stroke}"/>')
  else:out.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}" stroke="{stroke}"/>')
  lines=textwrap.wrap(label,32);start=y+h/2-(len(lines)-1)*10
  for i,line in enumerate(lines):out.append(f'<text x="{x+w/2}" y="{start+i*21}" fill="#182b44" font-size="16" font-weight="550" text-anchor="middle" dominant-baseline="middle">{esc(line)}</text>')
  out.append('</g>')
 out.append('</svg>');return ''.join(out)
